const mkRow = (nombre, overrides = {}) => {
  const { s1, s2, s3, s4, s5, s6, s7, s8, semanas, nota = "", rm = "", rir = "", descanso = "90", tipo = "normal", tabata = null, video = null, rol = null, sinDescansoSiguiente = false, ...rest } = overrides;
  const legacy = [s1, s2, s3, s4, s5, s6, s7, s8].filter((v) => v !== undefined);
  return {
    id: uid(), nombre, video, nota, rm, rir, descanso, tipo, rol, sinDescansoSiguiente,
    tabata: tabata || { trabajo: 20, descanso: 10, rounds: 8 },
    semanas: semanas || (legacy.length ? legacy : [""]),
    ...rest,
  };
};
const mkRowFromLibrary = (nombreLibreria, overrides = {}) => { const ex = findEx(nombreLibreria); return mkRow(ex ? ex.nombre : nombreLibreria, { video: ex ? ex.video : null, emoji: ex ? ex.emoji : null, ...overrides }); };
const mkBloque = (nombre, ejercicios = []) => ({ id: uid(), nombre, ejercicios });
const mkDia = (nombre, bloques = [], diaSemana = "") => ({ id: uid(), nombre, bloques, diaSemana });
const mkWarm = (nombre, series = "", reps = "", video = null) => ({ id: uid(), nombre, series, reps, video });
const DIAS_SEMANA = ["Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado", "Domingo"];
const todayISO = () => new Date().toISOString().slice(0, 10);
// Filtra check-ins (u otros registros con fecha "YYYY-MM-DD") para quedarnos solo con los del
// mes en curso — el gráfico "arranca de cero" visualmente cada mes, pero no se borra nada:
// el historial completo sigue guardado, solo dejamos de mostrarlo en el gráfico principal.
const delMesActual = (items) => {
  const prefijoMes = todayISO().slice(0, 7); // "YYYY-MM"
  return items.filter((c) => (c.fecha || "").startsWith(prefijoMes));
};
const fechaLegible = (iso) => { try { return new Date(iso + "T00:00:00").toLocaleDateString("es-AR", { day: "numeric", month: "short" }); } catch { return iso; } };
const mostrarFecha = (f) => (/^\d{4}-\d{2}-\d{2}$/.test(f) ? fechaLegible(f) : f);

function generarTextoPlan(alumno) {
  const p = alumno.plan;
  let t = `🐂 TEAM BULL — Plan de ${alumno.nombre}\n`;
  t += `Objetivo: ${p.meta.objetivo || "—"} | Actividad: ${p.meta.actividad || "—"} | Mesociclo: ${p.meta.mesociclo || "—"} | Fecha: ${p.meta.fecha || "—"}\n\n`;
  if (p.calentamiento.length) {
    t += `ENTRADA EN CALOR\n`;
    p.calentamiento.forEach((w) => { t += `• ${w.nombre}${w.series ? ` — ${w.series}x${w.reps || "?"}` : ""}\n`; });
    t += `\n`;
  }
  if (p.dias.length === 0) {
    t += `Todavía no hay días de entrenamiento cargados en este plan. Andá a la pestaña Plan y agregá al menos un día con ejercicios.\n`;
    return t;
  }
  p.dias.forEach((d) => {
    t += `${d.nombre}${d.diaSemana ? ` (${d.diaSemana})` : ""}\n`;
    if (d.bloques.length === 0 || d.bloques.every((b) => b.ejercicios.length === 0)) {
      t += `  (sin ejercicios cargados en este día)\n`;
    }
    d.bloques.forEach((b) => {
      t += `  ${b.nombre}\n`;
      b.ejercicios.forEach((f) => {
        if (f.tipo === "tabata") {
          t += `  • ${f.nombre} — Tabata ${f.tabata.trabajo}s/${f.tabata.descanso}s x${f.tabata.rounds}\n`;
        } else {
          const sems = f.semanas.filter(Boolean).join(" / ");
          t += `  • ${f.nombre}${f.nota ? ` (${f.nota})` : ""}${sems ? ` — ${sems}` : ""}${f.rm ? ` — RM: ${f.rm}` : ""}\n`;
        }
      });
    });
    t += `\n`;
  });
  return t;
}

function generarHTMLPlan(alumno) {
  const p = alumno.plan;
  const filaHTML = (f) => `<tr><td>${f.nombre}${f.nota ? ` <i>(${f.nota})</i>` : ""}</td>${f.tipo === "tabata" ? `<td colspan="99">Tabata: ${f.tabata.trabajo}s trabajo / ${f.tabata.descanso}s descanso × ${f.tabata.rounds} rounds</td>` : f.semanas.map((s) => `<td>${s || "—"}</td>`).join("") + `<td>${f.rm || "—"}</td>`}</tr>`;
  const diaHTML = (d) => `<h3>${d.nombre}${d.diaSemana ? ` — ${d.diaSemana}` : ""}</h3>` + d.bloques.map((b) => `<h4>${b.nombre}</h4><table><tr><th>Ejercicio</th>${b.ejercicios[0] && b.ejercicios[0].tipo !== "tabata" ? b.ejercicios[0].semanas.map((_, i) => `<th>Sem.${i + 1}</th>`).join("") + "<th>RM</th>" : "<th>Detalle</th>"}</tr>${b.ejercicios.map(filaHTML).join("")}</table>`).join("");
  return `<html><head><meta charset="utf-8"><title>Plan — ${alumno.nombre}</title><style>
    body{font-family:sans-serif;padding:24px;color:#111} h1{margin-bottom:0} h2{color:#FF6B35;margin-top:24px} h3{margin-bottom:4px} h4{color:#7DD6C0;margin:8px 0 4px}
    table{border-collapse:collapse;width:100%;margin-bottom:12px;font-size:12px} td,th{border:1px solid #ccc;padding:4px 6px;text-align:left}
    .meta span{margin-right:16px;color:#555}
    .btn-imprimir{display:inline-block;background:#FF6B35;color:#fff;border:none;border-radius:8px;padding:10px 16px;font-size:14px;font-weight:700;cursor:pointer;margin-bottom:16px}
    @media print{.btn-imprimir{display:none}}
  </style></head><body>
    <button class="btn-imprimir" onclick="window.print()">🖨️ Imprimir / Guardar como PDF</button>
    <h1>🐂 Team Bull</h1>
    <h2>${alumno.nombre}</h2>
    <div class="meta"><span><b>Objetivo:</b> ${p.meta.objetivo || "—"}</span><span><b>Actividad:</b> ${p.meta.actividad || "—"}</span><span><b>Mesociclo:</b> ${p.meta.mesociclo || "—"}</span><span><b>Fecha:</b> ${p.meta.fecha || "—"}</span></div>
    ${p.calentamiento.length ? `<h4>Entrada en calor</h4><table><tr><th>Ejercicio</th><th>Series</th><th>Reps</th></tr>${p.calentamiento.map((w) => `<tr><td>${w.nombre}</td><td>${w.series || "—"}</td><td>${w.reps || "—"}</td></tr>`).join("")}</table>` : ""}
    ${p.dias.map(diaHTML).join("")}
  </body></html>`;
}

// Enviar por WhatsApp directo (más confiable que el share nativo: no depende de permisos del navegador)
function compartirPorWhatsApp(alumno) {
  const texto = generarTextoPlan(alumno);
  const url = `https://wa.me/?text=${encodeURIComponent(texto)}`;
  window.open(url, "_blank", "noopener,noreferrer");
}

// Descarga el plan como archivo .html al dispositivo
function descargarPlanPDF(alumno) {
  const html = generarHTMLPlan(alumno);
  const blob = new Blob([html], { type: "text/html" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `Plan-${slugify(alumno.nombre)}.html`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

// Genera un solo documento con TODOS los alumnos, uno abajo del otro (con salto de página entre
// cada uno), para descargar de una sola vez en vez de tener que hacerlo alumno por alumno.
function generarHTMLPlantel(alumnos) {
  const secciones = alumnos.map((a) => {
    const html = generarHTMLPlan(a);
    // Sacamos el <html><head>...</head><body> de cada uno, nos quedamos solo con el contenido de adentro
    const match = html.match(/<body[^>]*>([\s\S]*)<\/body>/);
    return `<div style="page-break-before: always; padding-top: 20px;">${match ? match[1] : html}</div>`;
  }).join("");
  return `<html><head><meta charset="utf-8"><title>Team Bull — Plantel completo</title><style>
    body{font-family:sans-serif;padding:24px;color:#111} h1{margin-bottom:0} h2{color:#FF6B35;margin-top:24px} h3{margin-bottom:4px} h4{color:#7DD6C0;margin:8px 0 4px}
    table{border-collapse:collapse;width:100%;margin-bottom:12px;font-size:12px} td,th{border:1px solid #ccc;padding:4px 6px;text-align:left}
    .meta span{margin-right:16px;color:#555}
    .btn-imprimir{display:inline-block;background:#FF6B35;color:#fff;border:none;border-radius:8px;padding:10px 16px;font-size:14px;font-weight:700;cursor:pointer;margin-bottom:16px}
    @media print{.btn-imprimir{display:none}}
  </style></head><body>
    <button class="btn-imprimir" onclick="window.print()">🖨️ Imprimir / Guardar como PDF</button>
    <h1>🐂 Team Bull — Plantel completo (${alumnos.length} alumnos/as)</h1>
    ${secciones}
  </body></html>`;
}
function descargarPlantelPDF(alumnos) {
  const html = generarHTMLPlantel(alumnos);
  const blob = new Blob([html], { type: "text/html" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `TeamBull-Plantel-completo-${todayISO()}.html`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

// Abre el panel nativo de compartir (WhatsApp, copiar, mail, etc.) con el plan como texto,
// o si el dispositivo soporta compartir archivos, adjunta el HTML directamente.
async function compartirPlan(alumno) {
  const texto = generarTextoPlan(alumno);
  try {
    const html = generarHTMLPlan(alumno);
    const file = new File([html], `Plan-${slugify(alumno.nombre)}.html`, { type: "text/html" });
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({ files: [file], title: `Plan de ${alumno.nombre}`, text: texto });
      return;
    }
    if (navigator.share) {
      await navigator.share({ title: `Plan de ${alumno.nombre}`, text: texto });
      return;
    }
  } catch (e) {
    if (e && e.name === "AbortError") return; // el usuario canceló el share sheet
  }
  // Sin soporte de compartir nativo (ej: desktop): copiamos el texto al portapapeles
  try {
    await navigator.clipboard.writeText(texto);
    alert("Tu navegador no tiene menú para compartir. Copié el plan como texto al portapapeles — pegalo donde quieras (WhatsApp, mail, etc.).");
  } catch {
    descargarPlanPDF(alumno);
  }
}

// Compartir texto genérico por WhatsApp directo (usado por el informe semanal)
function compartirTextoPorWhatsApp(texto) {
  const url = `https://wa.me/?text=${encodeURIComponent(texto)}`;
  window.open(url, "_blank", "noopener,noreferrer");
}

// Compartir texto genérico (usado por el informe semanal)
async function compartirTexto(titulo, texto) {
  try {
    if (navigator.share) { await navigator.share({ title: titulo, text: texto }); return; }
  } catch (e) {
    if (e && e.name === "AbortError") return;
  }
  try {
    await navigator.clipboard.writeText(texto);
    alert("Copiado al portapapeles — pegalo donde quieras.");
  } catch {
    const blob = new Blob([texto], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = `${slugify(titulo)}.txt`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
  }
}

// Informe semanal consolidado: encuestas, check-ins y notas de ejercicios de los últimos 7 días, para todos los alumnos
function generarInformeSemanal(alumnos) {
  const hoy = new Date(todayISO() + "T00:00:00");
  const haceUnaSemana = new Date(hoy.getTime() - 7 * 24 * 60 * 60 * 1000);
  const enRango = (fechaStr) => {
    // fechas se guardan como ISO (YYYY-MM-DD) o texto libre tipo "13 ago" — solo filtramos las ISO, el resto se muestra igual
    if (/^\d{4}-\d{2}-\d{2}$/.test(fechaStr)) return new Date(fechaStr + "T00:00:00") >= haceUnaSemana;
    return true;
  };
  let t = `🐂 TEAM BULL — Informe semanal\n${fechaLegible(todayISO())}\n\n`;
  alumnos.forEach((a) => {
    t += `━━━━━━━━━━━━━━\n${a.nombre.toUpperCase()} · Cumplimiento: ${a.cumplimiento}%\n`;
    const checkinsRecientes = (a.wellness.checkins || []).filter((c) => enRango(c.fecha));
    if (checkinsRecientes.length) {
      const prom = (checkinsRecientes.reduce((s, c) => s + c.valor, 0) / checkinsRecientes.length).toFixed(1);
      t += `Ánimo (check-ins): promedio ${prom}/10 (${checkinsRecientes.length} registros)\n`;
    }
    const encuestasRecientes = (a.wellness.encuestas || []).filter((e) => enRango(e.fecha));
    if (encuestasRecientes.length) {
      t += `Encuestas post-entreno:\n`;
      encuestasRecientes.forEach((e) => {
        t += `  • Fatiga ${e.fatiga} · Sueño ${e.sueno} · Dolor ${e.dolorMuscular} · Motivación ${e.motivacion}${e.comentario ? ` — "${e.comentario}"` : ""}\n`;
      });
    }
    const notas = Object.values(a.notasEjercicios || {}).filter((n) => n.texto && n.texto.trim() && enRango(n.fecha));
    if (notas.length) {
      t += `Notas de ejercicios (peso, sensaciones):\n`;
      notas.forEach((n) => { t += `  • ${n.exNombre}: ${n.texto}\n`; });
    }
    const rmCargados = (a.plan?.rm || []).filter((r) => r.valor);
    if (rmCargados.length) {
      t += `Valores de RM cargados:\n`;
      rmCargados.forEach((r) => { t += `  • ${r.ejercicio}: ${r.valor}\n`; });
    }
    if (!checkinsRecientes.length && !encuestasRecientes.length && !notas.length && !rmCargados.length) {
      t += `Sin actividad registrada esta semana.\n`;
    }
    t += `\n`;
  });
  return t;
}

