        <button onClick={() => setSubTab("ia")} className="font-body" style={{ flex: 1, padding: "8px 0", borderRadius: 10, fontSize: 11, fontWeight: 700, cursor: "pointer", border: "1px solid #322E3D", background: subTab === "ia" ? "#7DD6C0" : "transparent", color: subTab === "ia" ? "#0B2A2E" : "#8B8698" }}>🐂 Bull Vision</button>
