function BuscarGlobal({ alumnos, templates, version, onGoAlumno, onGoPlantillas }) {
  const [q, setQ] = useState("");
  const query = q.trim().toLowerCase();

  const alumnosMatch = useMemo(() => (query ? alumnos.filter((a) => a.nombre.toLowerCase().includes(query)) : []), [query, alumnos]);
  const ejerciciosMatch = useMemo(() => (query ? EXERCISES.filter((e) => e.nombre.toLowerCase().includes(query)).slice(0, 25) : []), [query, version]);
  const plantillasMatch = useMemo(() => (query ? templates.filter((t) => t.nombre.toLowerCase().includes(query)) : []), [query, templates]);

  const sinResultados = query && alumnosMatch.length === 0 && ejerciciosMatch.length === 0 && plantillasMatch.length === 0;

  return (
    <div>
      <TopBar title="Buscar" subtitle="Alumnos/as, ejercicios y plantillas en un solo lugar" />
      <div style={{ padding: "0 20px" }}>
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Buscar cualquier cosa..." className="font-body" autoFocus
          style={{ width: "100%", background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 10, color: "#F4F1EA", padding: "11px 12px", fontSize: 13, marginBottom: 16, boxSizing: "border-box" }} />

        {!query && <div className="font-body" style={{ color: "#8B8698", fontSize: 12, textAlign: "center", padding: 20 }}>Escribí para buscar entre tu plantel, la biblioteca de ejercicios y tus plantillas.</div>}
        {sinResultados && <div className="font-body" style={{ color: "#8B8698", fontSize: 12, textAlign: "center", padding: 20 }}>Sin resultados para "{q}".</div>}

        {alumnosMatch.length > 0 && (
          <div style={{ marginBottom: 18 }}>
            <div className="font-body" style={{ fontSize: 11, color: "#FF6B35", fontWeight: 700, marginBottom: 8 }}>ALUMNOS/AS ({alumnosMatch.length})</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              {alumnosMatch.map((a) => (
                <button key={a.id} onClick={() => onGoAlumno(a.id)} className="font-body" style={{ display: "flex", alignItems: "center", gap: 10, background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 10, padding: 10, cursor: "pointer", textAlign: "left" }}>
                  <Avatar text={a.foto} size={28} />
                  <div style={{ flex: 1 }}>
                    <div style={{ color: "#F4F1EA", fontSize: 12, fontWeight: 600 }}>{a.nombre}</div>
                    <div style={{ color: "#8B8698", fontSize: 10 }}>{a.equipo || "Sin equipo"}</div>
                  </div>
                  <span style={{ color: "#8B8698" }}>›</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {ejerciciosMatch.length > 0 && (
          <div style={{ marginBottom: 18 }}>
            <div className="font-body" style={{ fontSize: 11, color: "#7DD6C0", fontWeight: 700, marginBottom: 8 }}>EJERCICIOS ({ejerciciosMatch.length}{ejerciciosMatch.length === 25 ? "+" : ""})</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              {ejerciciosMatch.map((e) => (
                <button key={e.id} onClick={() => openVideo(e.video)} className="font-body" style={{ display: "flex", alignItems: "center", gap: 10, background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 10, padding: 10, cursor: "pointer", textAlign: "left" }}>
                  <span style={{ fontSize: 16 }}>{e.emoji}</span>
                  <div style={{ flex: 1, color: "#F4F1EA", fontSize: 12, fontWeight: 600 }}>{e.nombre}</div>
                  <span style={{ color: e.color, fontSize: 9, fontWeight: 700 }}>{e.categoria}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {plantillasMatch.length > 0 && (
          <div style={{ marginBottom: 18 }}>
            <div className="font-body" style={{ fontSize: 11, color: "#8B8698", fontWeight: 700, marginBottom: 8 }}>PLANTILLAS ({plantillasMatch.length})</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              {plantillasMatch.map((t) => (
                <button key={t.id} onClick={onGoPlantillas} className="font-body" style={{ display: "flex", alignItems: "center", gap: 10, background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 10, padding: 10, cursor: "pointer", textAlign: "left" }}>
                  <div style={{ flex: 1 }}>
                    <div style={{ color: "#F4F1EA", fontSize: 12, fontWeight: 600 }}>{t.nombre}</div>
                    <div style={{ color: "#8B8698", fontSize: 10 }}>{t.categoria} · {t.plan.dias.length} días</div>
                  </div>
                  <span style={{ color: "#8B8698" }}>›</span>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

const REMEMBER_KEY = "teambull_remember_login";
function cargarLoginRecordado() {
  try {
    const raw = window.localStorage.getItem(REMEMBER_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function AuthScreen({ onLogin }) {
  const recordado = useRef(cargarLoginRecordado());
  const [usuario, setUsuario] = useState(recordado.current?.usuario || "");
  const [password, setPassword] = useState(recordado.current?.password || "");
  const [recordar, setRecordar] = useState(!!recordado.current);
  const [error, setError] = useState("");
  const intentar = (e) => {
    if (e && e.preventDefault) e.preventDefault();
    try {
      const u = usuario.trim(), p = password.trim();
      if (!onLogin(u, p)) { setError("Usuario o contraseña incorrectos."); return; }
      try {
        if (recordar) window.localStorage.setItem(REMEMBER_KEY, JSON.stringify({ usuario: u, password: p }));
        else window.localStorage.removeItem(REMEMBER_KEY);
      } catch {
        // localStorage no disponible: seguimos sin recordar
      }
    } catch (err) {
      // Si algo se rompe (por ejemplo datos guardados de una versión vieja), avisamos en vez de quedarnos sin hacer nada
      setError(`Hubo un problema al ingresar (${err?.message || "error desconocido"}). Probá restablecer los datos de este dispositivo, abajo.`);
    }
  };
  return (
    <form onSubmit={intentar} style={{ height: "100%", display: "flex", flexDirection: "column", justifyContent: "center", padding: "0 26px" }}>
      <div style={{ marginBottom: 16, textAlign: "center" }}><BullLogo size={170} /></div>
      <div className="font-display" style={{ fontSize: 26, color: "#F4F1EA", fontWeight: 700, marginBottom: 4, letterSpacing: 1, textAlign: "center" }}>TEAM BULL</div>
      <div className="font-body" style={{ fontSize: 12, color: "#8B8698", marginBottom: 24, textAlign: "center" }}>Entrenamiento de alto rendimiento</div>
      <div style={{ marginBottom: 12 }}>
        <div className="font-body" style={{ fontSize: 11, color: "#8B8698", marginBottom: 5 }}>Usuario</div>
        <input value={usuario} onChange={(e) => { setUsuario(e.target.value); setError(""); }} placeholder="tu usuario" name="username" autoComplete="username" className="font-body" style={{ width: "100%", background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 10, color: "#F4F1EA", padding: "11px 12px", fontSize: 13, boxSizing: "border-box" }} />
      </div>
      <div style={{ marginBottom: 10 }}>
        <div className="font-body" style={{ fontSize: 11, color: "#8B8698", marginBottom: 5 }}>Contraseña</div>
        <input value={password} onChange={(e) => { setPassword(e.target.value); setError(""); }} type="password" placeholder="••••••" name="current-password" autoComplete="current-password" className="font-body" style={{ width: "100%", background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 10, color: "#F4F1EA", padding: "11px 12px", fontSize: 13, boxSizing: "border-box" }} />
      </div>
      <label className="font-body" style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6, cursor: "pointer", userSelect: "none" }}>
        <input type="checkbox" checked={recordar} onChange={(e) => setRecordar(e.target.checked)} style={{ width: 16, height: 16, accentColor: "#FF6B35", cursor: "pointer" }} />
        <span style={{ fontSize: 12, color: "#8B8698" }}>Recordar contraseña en este dispositivo</span>
      </label>
      {error && <div className="font-body" style={{ color: "#E85D5D", fontSize: 11, marginBottom: 10 }}>{error}</div>}
      <button type="submit" className="font-body" style={{ width: "100%", background: "#FF6B35", color: "#121017", border: "none", borderRadius: 12, padding: "13px 0", fontWeight: 700, fontSize: 14, cursor: "pointer", marginTop: 8 }}>Ingresar</button>
      <div className="font-body" style={{ fontSize: 10, color: "#6B6678", marginTop: 14, textAlign: "center" }}>¿Sos alumno/a nuevo/a? Pedile el usuario y la contraseña a tu entrenador.</div>
      <div className="font-body" style={{ fontSize: 9, color: "#4A4658", marginTop: 10, textAlign: "center" }}>Tu navegador también puede ofrecerte guardar esta contraseña.</div>
      <button type="button" onClick={() => { if (window.confirm("¿Restablecer todos los datos guardados en este dispositivo? Esto no se puede deshacer.")) restablecerDatos(); }} className="font-body" style={{ background: "none", border: "none", color: "#4A4658", fontSize: 10, marginTop: 18, cursor: "pointer", textDecoration: "underline" }}>¿No podés entrar? Restablecer datos de este dispositivo</button>
    </form>
  );
}

