const ALERTAS_NOTIF_KEY = "teambull_alertas_notificadas_v1";
function cargarAlertasNotificadas() {
  try { return new Set(JSON.parse(window.localStorage.getItem(ALERTAS_NOTIF_KEY) || "[]")); } catch { return new Set(); }
}
function guardarAlertasNotificadas(set) {
  try { window.localStorage.setItem(ALERTAS_NOTIF_KEY, JSON.stringify([...set])); } catch {}
}
