function b64urlToUint8Array(b64url) {
  const padding = "=".repeat((4 - (b64url.length % 4)) % 4);
  const base64 = (b64url + padding).replace(/-/g, "+").replace(/_/g, "/");
  const raw = window.atob(base64);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
  return out;
}

// Pide permiso, registra el service worker y guarda la suscripción de este dispositivo en Supabase,
// asociada al usuario que inició sesión (coach o alumno/a).
async function activarNotificaciones(userId) {
  try {
    if (!("serviceWorker" in navigator) || !("PushManager" in window)) return { ok: false, motivo: "Este navegador no soporta notificaciones." };
    const permiso = await Notification.requestPermission();
    if (permiso !== "granted") return { ok: false, motivo: "No diste permiso para las notificaciones." };

    const reg = await navigator.serviceWorker.register("/sw.js");
    await navigator.serviceWorker.ready;
    let sub = await reg.pushManager.getSubscription();
    if (!sub) {
      sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: b64urlToUint8Array(VAPID_PUBLIC_KEY) });
    }

    await fetch(`${SUPABASE_URL}/rest/v1/push_subscriptions`, {
      method: "POST",
      headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${SUPABASE_KEY}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates" },
      body: JSON.stringify({ user_id: userId, subscription: sub.toJSON(), endpoint: sub.endpoint }),
    });
    return { ok: true };
  } catch (e) {
    return { ok: false, motivo: e.message || "Error inesperado." };
  }
}

// Avisa al servidor que le mande una notificación push a un usuario (se llama al enviar un mensaje de chat)
function enviarNotificacion(userId, title, body) {
  fetch("/api/notify", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ userId, title, body }),
  }).catch(() => {}); // si falla, no interrumpe el envío del mensaje en sí
}

async function cargarGuardadoRemoto() {
  try {
    const res = await fetch(SUPABASE_TABLE_URL, {
      headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${SUPABASE_KEY}` },
    });
    if (!res.ok) return { ok: false, data: null };
    const rows = await res.json();
    return { ok: true, data: rows?.[0]?.data || null };
  } catch {
    return { ok: false, data: null }; // sin internet o Supabase caído
  }
}
async function guardarTodoRemoto(data) {
  try {
    await fetch(SUPABASE_TABLE_URL, {
      method: "PATCH",
      headers: {
        apikey: SUPABASE_KEY,
        Authorization: `Bearer ${SUPABASE_KEY}`,
        "Content-Type": "application/json",
        Prefer: "return=minimal",
      },
      body: JSON.stringify({ data, updated_at: new Date().toISOString() }),
    });
  } catch {
    // sin internet: el cambio queda guardado localmente y se subirá en el próximo cambio con conexión
  }
}
function cargarGuardado() {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const data = JSON.parse(raw);
    if (data && typeof data._uidMax === "number" && data._uidMax > _uid) _uid = data._uidMax;
    return data;
  } catch {
    return null;
  }
}
function guardarTodo(data) {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...data, _uidMax: _uid }));
  } catch {
    // almacenamiento lleno o no disponible: seguimos sin persistir
  }
}
// "Repara" un alumno guardado en versiones anteriores completando los campos que puedan faltar,
// para que la app nunca se rompa por datos viejos en el dispositivo.
function sanearAlumno(a) {
  try {
    return {
      ...a,
      plan: {
        meta: { objetivo: "", actividad: "", macrociclo: "", mesociclo: "", fecha: "", fechaInicio: "", masaAdiposa: "", masaMuscular: "", descanso: "", ...(a.plan?.meta || {}) },
        calentamiento: Array.isArray(a.plan?.calentamiento) ? a.plan.calentamiento : [],
        dias: Array.isArray(a.plan?.dias) ? a.plan.dias : [],
        rm: Array.isArray(a.plan?.rm) ? a.plan.rm : [],
      },
      historialPeso: Array.isArray(a.historialPeso) ? a.historialPeso : [],
      rmSentadilla: Array.isArray(a.rmSentadilla) ? a.rmSentadilla : [],
      // Histórico de RM por ejercicio (no solo sentadilla) — migra automáticamente el histórico viejo
      // de sentadilla la primera vez, para no perder nada de lo que ya tenías cargado.
      historialRM: (() => {
        const existing = a.historialRM && typeof a.historialRM === "object" ? a.historialRM : {};
        if ((!existing.Sentadilla || existing.Sentadilla.length === 0) && Array.isArray(a.rmSentadilla) && a.rmSentadilla.length > 0) {
          return { ...existing, Sentadilla: a.rmSentadilla };
        }
        return existing;
      })(),
      wellness: { checkins: [], sesionesDesdeEncuesta: 0, encuestaPendiente: false, encuestas: [], ...(a.wellness || {}) },
      historialPlanes: Array.isArray(a.historialPlanes) ? a.historialPlanes : [],
      competencia: a.competencia && typeof a.competencia === "object" ? a.competencia : { nombre: "", fecha: "" },
      notasEjercicios: a.notasEjercicios && typeof a.notasEjercicios === "object" ? a.notasEjercicios : {},
      chat: Array.isArray(a.chat) ? a.chat : [],
      historialSesiones: Array.isArray(a.historialSesiones) ? a.historialSesiones : [],
      // Qué entrenadores pueden ver/editar a este alumno. "null" = todos los entrenadores lo ven
      // (así los alumnos que ya tenías cargados siguen visibles para todos, como antes). A partir
      // de ahora, un alumno nuevo queda privado del entrenador que lo crea, salvo que lo comparta.
      coachIds: Array.isArray(a.coachIds) ? a.coachIds : null,
    };
  } catch {
    return a;
  }
}
function sanearAlumnos(lista) {
  if (!Array.isArray(lista)) return null;
  try { return lista.map(sanearAlumno); } catch { return null; }
}
// Borra todos los datos guardados en este dispositivo y recarga la app desde cero
function restablecerDatos() {
  try {
    window.localStorage.removeItem(STORAGE_KEY);
    window.localStorage.removeItem(REMEMBER_KEY);
  } catch {
    // seguimos igual
  }
  window.location.reload();
}

export default function GymPlannerCoachApp() {
  const guardadoRef = useRef(null);
  if (guardadoRef.current === null) guardadoRef.current = cargarGuardado() || {};
  const guardado = guardadoRef.current;

  // Como la app es una sola pantalla que cambia lo que muestra por dentro (no tiene "páginas"
  // de verdad), atrapamos el botón de "atrás" del celular/navegador para que nunca te saque
  // a una pantalla en blanco — en vez de eso, no hace nada, y la navegación sigue siendo con
  // los botones de abajo (Inicio, Entrenar, etc.), como corresponde.
  useEffect(() => {
    window.history.pushState(null, "", window.location.href);
    const atraparAtras = () => window.history.pushState(null, "", window.location.href);
    window.addEventListener("popstate", atraparAtras);
    return () => window.removeEventListener("popstate", atraparAtras);
  }, []);

  const [session, setSession] = useState(null);
  const [coaches, setCoaches] = useState(guardado.coaches || COACHES_INICIAL);
  const [coachNombre, setCoachNombre] = useState(guardado.coachNombre || "Tomás Catani");
  const MENSAJE_RECORDATORIO_DEFAULT = "Hoy tenés entrenamiento — no te olvides de contarle a tu coach cómo venís.";
  const [mensajeRecordatorio, setMensajeRecordatorio] = useState(guardado.mensajeRecordatorio || MENSAJE_RECORDATORIO_DEFAULT);
  const [notificacionesActivas, setNotificacionesActivasState] = useState(cargarPreferenciaNotificaciones());
  const setNotificacionesActivas = (v) => { setNotificacionesActivasState(v); guardarPreferenciaNotificaciones(v); };
  const [modoPausa, setModoPausa] = useState(guardado.modoPausa || false);
  const [diasAvisoPlan, setDiasAvisoPlan] = useState(guardado.diasAvisoPlan || 7);
  const [rolesPersonalizados, setRolesPersonalizados] = useState(guardado.rolesPersonalizados || []);
  const agregarRolPersonalizado = (label, color) => setRolesPersonalizados((prev) => [...prev, { id: `custom_${uid()}`, label, color }]);
  const [alumnos, setAlumnos] = useState(sanearAlumnos(guardado.alumnos) || sanearAlumnos(ALUMNOS_INICIAL));
  const [templates, setTemplates] = useState(guardado.templates || TEMPLATES_INICIAL);
  const [selectedCoachAlumno, setSelectedCoachAlumno] = useState(null);
  const [tab, setTab] = useState("dashboard");
  const [libVersion, setLibVersion] = useState(0);
  const [guardadoOk, setGuardadoOk] = useState(false);
  // Esperamos a traer los datos compartidos de Supabase antes de dejar guardar,
  // así no pisamos lo que cargaron otros dispositivos con los datos iniciales de este.
  const [remotoListo, setRemotoListo] = useState(false);
  // Solo confirmamos "sincronizado" cuando logramos traer la versión real de la nube.
  // Si nunca se confirma, no dejamos que la app suba nada — así evitamos pisar cambios
  // hechos desde otro celular por una mala conexión momentánea en este.
  const remotoSincronizadoRef = useRef(false);
  const [remotoSincronizado, setRemotoSincronizado] = useState(false);

  useEffect(() => {
    let cancelado = false;
    (async () => {
      let intento = await cargarGuardadoRemoto();
      // Si falla, reintentamos un par de veces más antes de resignarnos — una mala conexión
      // momentánea no debería hacer que arranquemos "a ciegas" con datos locales viejos.
      for (let i = 0; i < 2 && !intento.ok && !cancelado; i++) {
        await new Promise((r) => setTimeout(r, 1200));
        intento = await cargarGuardadoRemoto();
      }
      if (cancelado) return;
      if (intento.ok) {
        remotoSincronizadoRef.current = true;
        setRemotoSincronizado(true);
        const remoto = intento.data;
        if (remoto) {
          if (remoto.coachNombre) setCoachNombre(remoto.coachNombre);
          if (remoto.mensajeRecordatorio) setMensajeRecordatorio(remoto.mensajeRecordatorio);
          if (typeof remoto.modoPausa === "boolean") setModoPausa(remoto.modoPausa);
          if (typeof remoto.diasAvisoPlan === "number") setDiasAvisoPlan(remoto.diasAvisoPlan);
          if (Array.isArray(remoto.rolesPersonalizados)) setRolesPersonalizados(remoto.rolesPersonalizados);
          if (remoto.coaches) setCoaches(remoto.coaches);
          if (remoto.alumnos) setAlumnos(sanearAlumnos(remoto.alumnos) || ALUMNOS_INICIAL);
          setTemplates(combinarPlantillas(remoto.templates));
          if (typeof remoto._uidMax === "number" && remoto._uidMax > _uid) _uid = remoto._uidMax;
        }
      }
      setRemotoListo(true);
    })();
    return () => { cancelado = true; };
  }, []);

  // Si no logramos sincronizar al principio, seguimos intentando cada 15s en segundo plano
  // (por si la conexión vuelve durante la sesión), antes de habilitar el guardado en la nube.
  useEffect(() => {
    if (remotoSincronizado) return;
    const intervalo = setInterval(async () => {
      const intento = await cargarGuardadoRemoto();
      if (intento.ok) {
        remotoSincronizadoRef.current = true;
        setRemotoSincronizado(true);
        const remoto = intento.data;
        if (remoto) {
          if (remoto.coachNombre) setCoachNombre(remoto.coachNombre);
          if (remoto.mensajeRecordatorio) setMensajeRecordatorio(remoto.mensajeRecordatorio);
          if (typeof remoto.modoPausa === "boolean") setModoPausa(remoto.modoPausa);
          if (typeof remoto.diasAvisoPlan === "number") setDiasAvisoPlan(remoto.diasAvisoPlan);
          if (Array.isArray(remoto.rolesPersonalizados)) setRolesPersonalizados(remoto.rolesPersonalizados);
          if (remoto.coaches) setCoaches(remoto.coaches);
          if (remoto.alumnos) setAlumnos(sanearAlumnos(remoto.alumnos) || ALUMNOS_INICIAL);
          setTemplates(combinarPlantillas(remoto.templates));
        }
      }
    }, 15000);
    return () => clearInterval(intervalo);
  }, [remotoSincronizado]);

  useEffect(() => {
    if (!remotoListo) return; // todavía no trajimos lo compartido: no guardamos para no pisarlo
    const data = { coachNombre, coaches, alumnos, templates, mensajeRecordatorio, modoPausa, diasAvisoPlan, rolesPersonalizados, _uidMax: _uid };
    guardarTodo(data); // copia local rápida (funciona siempre, con o sin internet)
    if (remotoSincronizadoRef.current) {
      guardarTodoRemoto(data); // solo subimos a la nube si confirmamos que arrancamos con la versión real compartida
    }
    setGuardadoOk(true);
    const t = setTimeout(() => setGuardadoOk(false), 1200);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [coachNombre, coaches, alumnos, templates, mensajeRecordatorio, modoPausa, diasAvisoPlan, rolesPersonalizados, remotoListo]);

  // Le avisa al coach por notificación push apenas aparece una alerta nueva (ánimo bajo, cumplimiento
  // bajo, etc.). Guardamos cuáles ya se avisaron en este dispositivo (no solo en la memoria de esta
  // sesión) para que no te vuelva a mandar la misma notificación cada vez que abrís la app.
  const alertasNotificadasRef = useRef(null);
  if (alertasNotificadasRef.current === null) alertasNotificadasRef.current = cargarAlertasNotificadas();
  useEffect(() => {
    if (!remotoListo || !notificacionesActivas) return;
    const alertasActuales = alumnos.flatMap((a) => generarAlertas(a).map((al) => ({ ...al, key: `${a.id}::${al.titulo}` })));
    const clavesActuales = new Set(alertasActuales.map((al) => al.key));
    let cambio = false;
    for (const al of alertasActuales) {
      if (!alertasNotificadasRef.current.has(al.key)) {
        alertasNotificadasRef.current.add(al.key);
        cambio = true;
        enviarNotificacion("coach", al.titulo, al.detalle);
      }
    }
    // Si una alerta ya no está activa (se solucionó), la sacamos del historial — así, si el mismo
    // problema vuelve a pasar más adelante, te vuelve a avisar en vez de quedar callada para siempre.
    for (const key of [...alertasNotificadasRef.current]) {
      if (!clavesActuales.has(key)) { alertasNotificadasRef.current.delete(key); cambio = true; }
    }
    if (cambio) guardarAlertasNotificadas(alertasNotificadasRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [alumnos, remotoListo, notificacionesActivas]);
  const addCustomExercise = (ex) => { EXERCISES.push(ex); setLibVersion((v) => v + 1); };
  const toggleFavorito = (id) => { FAVORITOS_SET.has(id) ? FAVORITOS_SET.delete(id) : FAVORITOS_SET.add(id); setLibVersion((v) => v + 1); };
  // Edita el video de un ejercicio de la biblioteca de forma permanente: le queda guardado a ese
  // ejercicio para cualquier plan donde se use de ahí en más (no solo en un plan puntual).
  const editarVideoLibreria = (id, video) => {
    const ex = EXERCISES.find((e) => e.id === id);
    if (ex) ex.video = video || `https://www.youtube.com/results?search_query=${encodeURIComponent(ex.nombre + " técnica")}`;
    setLibVersion((v) => v + 1);
  };

  const login = (usuario, password) => {
    const c = coaches.find((co) => co.usuario === usuario && co.password === password);
    if (c) { setSession({ role: "coach", coachId: c.id }); setTab("dashboard"); return true; }
    const a = alumnos.find((al) => al.usuario === usuario && al.password === password);
    if (a) { setSession({ role: "athlete", athleteId: a.id }); setTab("inicio"); return true; }
    return false;
  };
  const logout = () => { setSession(null); setSelectedCoachAlumno(null); };
  const addCoach = (d) => {
    const usuario = slugify(d.nombre.trim()) || `coach${coaches.length + 1}`;
    const password = Math.random().toString().slice(2, 6);
    const nuevo = { id: uid(), nombre: d.nombre.trim(), usuario, password };
    setCoaches((prev) => [...prev, nuevo]);
    return { usuario, password };
  };
  const removeCoach = (coachId) => setCoaches((prev) => (prev.length > 1 ? prev.filter((c) => c.id !== coachId) : prev));
  // Cambia la contraseña del coach que está usando la app en este momento (valida la actual antes).
  const cambiarPasswordCoach = (coachId, actual, nueva) => {
    const c = coaches.find((co) => co.id === coachId);
    if (!c) return { ok: false, motivo: "No se encontró tu usuario." };
    if (c.password !== actual) return { ok: false, motivo: "La contraseña actual no coincide." };
    if (!nueva || nueva.length < 4) return { ok: false, motivo: "La contraseña nueva necesita al menos 4 caracteres." };
    setCoaches((prev) => prev.map((co) => (co.id === coachId ? { ...co, password: nueva } : co)));
    return { ok: true };
  };

  const asignarPlantilla = (alumnoId, templateId) => {
    const tpl = templates.find((t) => t.id === templateId);
    setAlumnos((prev) => prev.map((a) => (a.id === alumnoId ? { ...a, plan: clonarPlan(tpl.plan) } : a)));
  };
  const copiarPlan = (origenId, destinoId) => {
    const origen = alumnos.find((a) => a.id === origenId);
    if (!origen) return;
    setAlumnos((prev) => prev.map((a) => (a.id === destinoId ? { ...a, plan: clonarPlan(origen.plan) } : a)));
  };
  // Convierte el plan actual de un/a alumno/a en una plantilla nueva y reutilizable — no toca
  // el plan original de esa persona, es una copia independiente.
  const guardarComoPlantilla = (alumnoId, nombre) => {
    const origen = alumnos.find((a) => a.id === alumnoId);
    if (!origen) return;
    crearPlantilla({ id: uid(), nombre, categoria: "Personalizada", plan: clonarPlan(origen.plan) });
  };
  const updatePlan = (alumnoId, newPlan) => setAlumnos((prev) => prev.map((a) => (a.id === alumnoId ? { ...a, plan: newPlan } : a)));
  const updateAlumno = (alumnoId, patch) => setAlumnos((prev) => prev.map((a) => (a.id === alumnoId ? { ...a, ...patch } : a)));
  const deleteAlumno = (alumnoId) => setAlumnos((prev) => prev.filter((a) => a.id !== alumnoId));
  const guardarVersion = (alumnoId, nombre) => setAlumnos((prev) => prev.map((a) => (a.id === alumnoId ? { ...a, historialPlanes: [{ id: uid(), nombre, fecha: todayISO(), plan: clonarPlan(a.plan) }, ...a.historialPlanes] } : a)));
  const restaurarVersion = (alumnoId, versionId) => setAlumnos((prev) => prev.map((a) => {
    if (a.id !== alumnoId) return a;
    const v = a.historialPlanes.find((x) => x.id === versionId);
    return v ? { ...a, plan: clonarPlan(v.plan) } : a;
  }));
  const registrarCheckin = (alumnoId, valor) => setAlumnos((prev) => prev.map((a) => (a.id === alumnoId ? { ...a, wellness: { ...a.wellness, checkins: [...a.wellness.checkins, { fecha: todayISO(), valor }] } } : a)));
  const updateNota = (alumnoId, exId, exNombre, texto) => setAlumnos((prev) => prev.map((a) => (a.id === alumnoId ? { ...a, notasEjercicios: { ...(a.notasEjercicios || {}), [exId]: { texto, exNombre, fecha: todayISO() } } } : a)));
  // Guarda un nuevo punto en el histórico de RM de un ejercicio puntual (no solo sentadilla),
  // para que cualquier levantamiento que cargues tenga su propio gráfico de evolución.
  const agregarHistorialRM = (alumnoId, ejercicio, valor) => {
    setAlumnos((prev) => prev.map((a) => {
      if (a.id !== alumnoId) return a;
      const actual = (a.historialRM && a.historialRM[ejercicio]) || [];
      if (actual[actual.length - 1] === valor) return a; // sin cambios reales, no duplicar
      return { ...a, historialRM: { ...(a.historialRM || {}), [ejercicio]: [...actual, valor] } };
    }));
  };

  const finalizarEntrenamiento = (alumnoId) => {
    setAlumnos((prev) => prev.map((a) => (a.id === alumnoId ? { ...a, sesionesCompletadas: (a.sesionesCompletadas || 0) + 1, historialSesiones: [...(a.historialSesiones || []), todayISO()], wellness: { ...a.wellness, encuestaPendiente: true } } : a)));
  };
  const enviarEncuestaSemanal = (alumnoId, data) => setAlumnos((prev) => prev.map((a) => (a.id === alumnoId ? { ...a, wellness: { ...a.wellness, encuestas: [{ fecha: "hoy", ...data }, ...a.wellness.encuestas], encuestaPendiente: false } } : a)));
  const addAlumno = (d) => {
    const iniciales = d.nombre.trim().split(" ").map((n) => n[0]).slice(0, 2).join("").toUpperCase() || "??";
    const usuario = slugify(d.nombre.trim()) || `alumno${alumnos.length + 1}`;
    const password = Math.random().toString().slice(2, 6);
    setAlumnos((prev) => [...prev, { id: uid(), nombre: d.nombre.trim(), usuario, password, edad: d.edad || "", peso: d.peso || "", altura: d.altura || "", objetivo: d.objetivo || "", deportes: d.deportes || "", nivel: d.nivel || "Intermedio", lesiones: "Ninguna", inicio: "", equipo: d.equipo || "", cumplimiento: 0, foto: iniciales, sesionesCompletadas: 0, plan: mkPlanVacio(), historialPeso: [], rmSentadilla: [], wellness: mkWellness(), historialPlanes: [], competencia: { nombre: "", fecha: "" }, notasEjercicios: {}, chat: [], coachIds: session?.coachId ? [session.coachId] : null }]);
    return { usuario, password };
  };
  // Le da acceso a otro entrenador a un alumno puntual (los dos lo ven y lo pueden editar de ahí en
  // más). No saca al entrenador original — se suma, no reemplaza.
  const compartirAlumnoConCoach = (alumnoId, otroCoachId) => {
    setAlumnos((prev) => prev.map((a) => {
      if (a.id !== alumnoId) return a;
      const actuales = a.coachIds === null ? coaches.map((c) => c.id) : a.coachIds;
      return { ...a, coachIds: actuales.includes(otroCoachId) ? actuales : [...actuales, otroCoachId] };
    }));
  };
  const dejarDeCompartirAlumno = (alumnoId, coachIdAQuitar) => {
    setAlumnos((prev) => prev.map((a) => {
      if (a.id !== alumnoId) return a;
      const actuales = a.coachIds === null ? coaches.map((c) => c.id) : a.coachIds;
      return { ...a, coachIds: actuales.filter((id) => id !== coachIdAQuitar) };
    }));
  };
  const crearPlantilla = (tpl) => setTemplates((prev) => [...prev, tpl]);
  const sendMsg = (alumnoId, from, texto) => {
    setAlumnos((prev) => prev.map((a) => (a.id === alumnoId ? { ...a, chat: [...a.chat, { from, texto, hora: "ahora" }] } : a)));
    if (from === "coach") {
      enviarNotificacion(alumnoId, `Mensaje de ${coachNombre}`, texto);
    } else {
      const alumnoQueEscribe = alumnos.find((a) => a.id === alumnoId);
      enviarNotificacion("coach", `Mensaje de ${alumnoQueEscribe?.nombre || "un/a alumno/a"}`, texto);
    }
  };

  const athlete = session?.role === "athlete" ? alumnos.find((a) => a.id === session.athleteId) : null;

  let body;
  if (!remotoListo) {
    body = (
      <div style={{ height: "100%", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 14 }}>
        <BullLogo size={100} />
        <div className="font-body" style={{ color: "#8B8698", fontSize: 12 }}>Conectando...</div>
      </div>
    );
  } else if (!session) {
    body = <AuthScreen onLogin={login} />;
  } else if (session.role === "coach") {
    // Un alumno con coachIds = null es "de todos" (así quedan los que ya tenías antes de esta
    // función). Uno con coachIds = [...] solo lo ven los entrenadores que estén en esa lista.
    const alumnosVisibles = alumnos.filter((a) => a.coachIds === null || a.coachIds.includes(session.coachId));
    if (tab === "dashboard") body = <CoachDashboard alumnos={alumnosVisibles} goAlumnos={(id) => { setTab("alumnos"); setSelectedCoachAlumno(id); }} coachNombre={coachNombre} onUpdateCoach={setCoachNombre} coaches={coaches} onAddCoach={addCoach} onRemoveCoach={removeCoach} mensajeRecordatorio={mensajeRecordatorio} onUpdateMensajeRecordatorio={setMensajeRecordatorio} notificacionesActivas={notificacionesActivas} onToggleNotificaciones={setNotificacionesActivas} modoPausa={modoPausa} onToggleModoPausa={setModoPausa} diasAvisoPlan={diasAvisoPlan} onSetDiasAvisoPlan={setDiasAvisoPlan} coachId={session?.coachId} onCambiarPassword={cambiarPasswordCoach} />;
    else if (tab === "alumnos") body = <CoachAlumnos alumnos={alumnosVisibles} selectedId={selectedCoachAlumno} setSelectedId={setSelectedCoachAlumno} templates={templates} onAsignarPlantilla={asignarPlantilla} onCopiarPlan={copiarPlan} onGuardarComoPlantilla={guardarComoPlantilla} onUpdatePlan={updatePlan} onUpdateAlumno={updateAlumno} onDeleteAlumno={deleteAlumno} onAddAlumno={addAlumno} onSendMsg={sendMsg} onGuardarVersion={guardarVersion} onRestaurarVersion={restaurarVersion} onGuardarHistorialRM={agregarHistorialRM} onAddToLibrary={addCustomExercise} version={libVersion} coaches={coaches} coachIdActual={session.coachId} onCompartirAlumno={compartirAlumnoConCoach} onDejarDeCompartir={dejarDeCompartirAlumno} rolesPersonalizados={rolesPersonalizados} onAgregarRolPersonalizado={agregarRolPersonalizado} />;
    else if (tab === "plantillas") body = <CoachPlantillas templates={templates} alumnos={alumnosVisibles} onAsignar={asignarPlantilla} onCrearPlantilla={crearPlantilla} onAddToLibrary={addCustomExercise} version={libVersion} rolesPersonalizados={rolesPersonalizados} onAgregarRolPersonalizado={agregarRolPersonalizado} />;
    else if (tab === "ejercicios") body = <CoachEjercicios onAddExercise={addCustomExercise} version={libVersion} onToggleFav={toggleFavorito} onEditVideo={editarVideoLibreria} />;
    else body = <BuscarGlobal alumnos={alumnosVisibles} templates={templates} version={libVersion} onGoAlumno={(id) => { setTab("alumnos"); setSelectedCoachAlumno(id); }} onGoPlantillas={() => setTab("plantillas")} />;
  } else if (!athlete) {
    body = <div className="font-body" style={{ color: "#8B8698", fontSize: 13, textAlign: "center", padding: "40px 20px" }}>Tu cuenta ya no está activa. Consultá con tu entrenador.</div>;
  } else if (athlete.wellness.encuestaPendiente && tab !== "entrenar") {
    body = (
      <div style={{ position: "relative", minHeight: "100%" }}>
        <AthleteInicio alumno={athlete} goEntrenar={() => setTab("entrenar")} onCheckin={registrarCheckin} />
        <EncuestaSemanalModal onClose={() => updateAlumno(athlete.id, { wellness: { ...athlete.wellness, encuestaPendiente: false } })} onSubmit={(data) => enviarEncuestaSemanal(athlete.id, data)} />
      </div>
    );
  } else {
    if (tab === "inicio") body = <AthleteInicio alumno={athlete} goEntrenar={() => setTab("entrenar")} onCheckin={registrarCheckin} />;
    else if (tab === "entrenar") body = <AthleteEntrenar alumno={athlete} onFinalizar={(id) => { finalizarEntrenamiento(id); setTab("inicio"); }} onUpdateNota={(exId, exNombre, texto) => updateNota(athlete.id, exId, exNombre, texto)} rolesPersonalizados={rolesPersonalizados} />;
    else if (tab === "progreso") body = <AthleteProgreso alumno={athlete} onGuardarHistorialRM={(ejercicio, valor) => agregarHistorialRM(athlete.id, ejercicio, valor)} />;
    else if (tab === "nutricion") body = <CalculadoraScreen alumno={athlete} />;
    else body = <ChatScreen alumno={athlete} onSendMsg={sendMsg} />;
  }
  const tabs = session?.role === "coach" ? COACH_TABS : ATHLETE_TABS;

  // Detecta si estamos en una pantalla de celular real, para que ahí la app ocupe todo
  // (sin el marco decorativo de celular que solo tiene sentido viéndolo desde una compu)
  const [isMobile, setIsMobile] = useState(() => (typeof window !== "undefined" ? window.innerWidth <= 640 : false));
  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth <= 640);
    window.addEventListener("resize", check);
    return () => window.removeEventListener("resize", check);
  }, []);

  const appShell = (
    <div style={{ width: isMobile ? "100%" : 375, height: isMobile ? "100%" : 720, background: "#121017", borderRadius: isMobile ? 0 : 36, border: isMobile ? "none" : "8px solid #1C1A24", boxShadow: isMobile ? "none" : "0 30px 60px rgba(0,0,0,0.5)", overflow: "hidden", display: "flex", flexDirection: "column", position: "relative", zIndex: 1 }}>
      {/* Patrón sutil de siluetas de gimnasio detrás del contenido, dentro de la app */}
      <div style={{ position: "absolute", inset: 0, backgroundImage: `url(${GYM_PATTERN_B64})`, backgroundRepeat: "repeat", backgroundSize: "150px 150px", opacity: 0.06, pointerEvents: "none", zIndex: 0 }} />
      {session && (
        <button onClick={logout} className="font-body" style={{ position: "absolute", top: "calc(14px + env(safe-area-inset-top, 0px))", right: 14, zIndex: 5, background: "#1C1A24", border: "1px solid #322E3D", borderRadius: 999, color: "#8B8698", fontSize: 10, fontWeight: 700, padding: "5px 10px", cursor: "pointer" }}>Cerrar sesión</button>
      )}
      {session && session.role === "coach" && (
        <div className="font-body" style={{ position: "absolute", top: "calc(16px + env(safe-area-inset-top, 0px))", left: 14, zIndex: 5, fontSize: 9, color: !remotoSincronizado ? "#FF6B35" : guardadoOk ? "#33D6A6" : "#4A4658", transition: "color 0.3s" }}>{!remotoSincronizado ? "⚠ Sin conexión con la nube" : guardadoOk ? "✓ Guardado" : "●"}</div>
      )}
      <div style={{ flex: 1, overflowY: "auto", paddingBottom: 8, paddingTop: "env(safe-area-inset-top, 0px)", position: "relative", zIndex: 1 }}>{body}</div>
      {session && (
        <div style={{ display: "flex", borderTop: "1px solid #26232F", background: "#151319", padding: "8px 4px calc(8px + env(safe-area-inset-bottom, 0px))", position: "relative", zIndex: 1 }}>
          {tabs.map((t) => (
            <button key={t.id} onClick={() => setTab(t.id)} style={{ flex: 1, background: "none", border: "none", cursor: "pointer", display: "flex", flexDirection: "column", alignItems: "center", gap: 2 }}>
              <span style={{ fontSize: 15, opacity: tab === t.id ? 1 : 0.45 }}>{t.icon}</span>
              <span className="font-body" style={{ fontSize: 8, fontWeight: 600, color: tab === t.id ? (session.role === "coach" ? "#FF6B35" : "#7DD6C0") : "#8B8698" }}>{t.label}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );

  if (isMobile) {
    // En el celular: la app ocupa toda la pantalla, sin marco ni texto decorativo, como una app real
    return (
      <div style={{ width: "100vw", height: "100dvh", background: "#0B0A0F", overflow: "hidden" }}>
        {FONTS}
        {appShell}
        <VideoModal />
      </div>
    );
  }

  return (
    <div style={{ minHeight: "100vh", background: "#0B0A0F", display: "flex", flexDirection: "column", alignItems: "center", padding: 24, gap: 14, position: "relative", overflow: "hidden" }}>
      {FONTS}
      {appShell}
      <VideoModal />
    </div>
  );
}
